import { createAsyncThunk, createSlice } from "@reduxjs/toolkit"; // (import Redux tools)
import axios from "axios"; // (for backend requests)

// (Initial Redux state)
const initialState = {
  users: [], // (stores all registered users)
  user: {}, // (stores current logged-in user)
  isLoading: false, // (shows loading while waiting)
  isSuccess: false, // (true when request succeeds)
  isError: false, // (true when request fails)
};

// (Register new student user)
export const registerUser = createAsyncThunk(
  "users/registerUser",
  async (data, thunkAPI) => {
    try {
      const res = await axios.post("http://localhost:3001/registerUser", data);
      if (!res.data || !res.data.user) {
        return thunkAPI.rejectWithValue(res.data?.error || "User not returned");
      }
      return res.data.user;
    } catch (err) {
      console.error("registerUser error:", err.response?.data || err.message);
      return thunkAPI.rejectWithValue(err.response?.data || "Error");
    }
  }
);

// (Login existing user)
export const login = createAsyncThunk("users/login", async (data, thunkAPI) => {
  try {
    const res = await axios.post("http://localhost:3001/login", data); // (send login data)
    return res.data; // (get { user, role } from backend)
  } catch (err) {
    return thunkAPI.rejectWithValue(err.response?.data || "Login failed"); // (catch error)
  }
});

// (Logout current user)
export const logout = createAsyncThunk("users/logout", async () => {
  try {
    await axios.post("http://localhost:3001/logout"); // (send logout request to backend)
  } catch (err) {
    console.error("Logout error:", err); // (show error if failed)
  }
});

// (Fetch user by email from MongoDB)
export const fetchUser = createAsyncThunk("users/fetchUser", async (email) => {
  const res = await axios.get(`http://localhost:3001/user/${email}`); // (get specific user)
  return res.data; // (return user info)
});

// (Main Redux slice)
const userSlice = createSlice({
  name: "users", // (slice name for Redux)
  initialState,
  reducers: {
    deleteUser: (s, a) => {
      s.users = s.users.filter((u) => u.email !== a.payload);
    }, // (remove user from local array)
  },
  extraReducers: (b) => {
    b
      // (Register handlers)
      .addCase(registerUser.pending, (s) => {
        s.isLoading = true;
      }) // (when waiting)
      .addCase(registerUser.fulfilled, (s, a) => {
        s.isLoading = false;
        s.isSuccess = true;
        s.users.push(a.payload);
      }) // (when done successfully)
      .addCase(registerUser.rejected, (s) => {
        s.isLoading = false;
        s.isError = true;
      }) // (when failed)

      // (Login handlers)
      .addCase(login.pending, (s) => {
        s.isLoading = true;
      }) // (while loading)
      .addCase(login.fulfilled, (s, a) => {
        s.isLoading = false;
        s.isSuccess = true;
        s.user = a.payload.user; // (save logged user)
        s.user.role = a.payload.role; // (save role: student/company)
      })
      .addCase(login.rejected, (s) => {
        s.isLoading = false;
        s.isError = true;
      }) // (login failed)

      // (Logout handlers)
      .addCase(logout.fulfilled, (s) => {
        s.user = {};
        s.isSuccess = false;
      }) // (clear user after logout)

      // (Fetch user handler)
      .addCase(fetchUser.fulfilled, (s, a) => {
        s.user = a.payload;
        s.isSuccess = true;
      }); // (save fetched user)
  },
});

export const { deleteUser } = userSlice.actions; // (export reducer actions)
export default userSlice.reducer; // (export for Store.js)
